pub type GameSettings = { difficulty: Int; volume: Float64; fullscreen: Bool; }

impl Default for GameSettings {
  fn default() -> GameSettings {
    return GameSettings{ difficulty: 1, volume: 0.5, fullscreen: false };
  }
}

fn main() -> Int {
  let s = GameSettings::default();
  return s.difficulty * 100 + (s.volume * 100.0) as Int;
}
